//! The mandatory migration proof (design doc §14.4, §19.2 C):
//!
//! * release A creates `library.book` and is populated;
//! * release B adds `slug`, backfills it with a data migration written
//!   against B's schema, then makes it required;
//! * release C renames the column `title` → `name` and the table
//!   `books` → `library_books` (same stable IDs);
//! * no current Rust type for books exists anywhere: the data step names
//!   the model and fields by stable ID and key only.
//!
//! Every migration is generated by the planner from model declarations.
//! A fresh database replaying all history and a populated release-A
//! database upgraded in place converge on the same verified schema.

use std::collections::BTreeSet;

use serde_json::{Value, json};
use sqlx::PgConnection;
use trestle_historical::artifact::{self, Artifact};
use trestle_historical::data::{DataFuture, DataRun, DataStep, HistoricalTx};
use trestle_historical::planner::{PlanOptions, diff};
use trestle_historical::schema::{Column, Model, desired};
use trestle_historical::testing::TestDatabase;
use trestle_historical::verify::verify;
use trestle_historical::{HistoryError, Migration, MigrationRef, MigrationSet, migrate};

fn leak(text: String) -> &'static str {
    Box::leak(text.into_boxed_str())
}

fn to_migration(artifact: &Artifact, data: Option<DataStep>) -> Migration {
    let depends_on: Vec<MigrationRef> = artifact
        .manifest
        .depends_on
        .iter()
        .map(|d| {
            let (app, id) = d.split_once('.').unwrap();
            MigrationRef::new(leak(app.into()), leak(id.into()))
        })
        .collect();
    Migration {
        app: leak(artifact.manifest.app.clone()),
        id: leak(artifact.manifest.id.clone()),
        depends_on: Box::leak(depends_on.into_boxed_slice()),
        sql: leak(artifact.sql.clone()),
        manifest: Some(leak(artifact.manifest_json())),
        data,
    }
}

fn slugify(title: &str) -> String {
    let dashed: String = title
        .chars()
        .map(|c| {
            if c.is_alphanumeric() {
                c.to_lowercase().next().unwrap()
            } else {
                '-'
            }
        })
        .collect();
    dashed
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-")
}

/// Written against release B's schema. It keeps replaying after release C
/// renames `title`'s column, because fields resolve through history.
fn backfill_slugs<'a>(tx: &'a mut HistoricalTx<'_>) -> DataFuture<'a> {
    Box::pin(async move {
        let mut after: Option<Value> = None;
        loop {
            // A tiny batch size exercises paging.
            let rows = tx
                .batch("library.book", &["title", "slug"], after.as_ref(), 2)
                .await?;
            let Some(last) = rows.last() else { break };
            after = Some(last["id"].clone());
            for row in &rows {
                if row["slug"].is_null() {
                    let slug = slugify(row["title"].as_str().unwrap_or_default());
                    tx.update("library.book", &row["id"], &[("slug", json!(slug))])
                        .await?;
                }
            }
        }
        Ok(())
    })
}

const BACKFILL: DataStep = DataStep {
    name: "backfill_slugs",
    source: include_str!("evolution.rs"),
    run: DataRun::Once(backfill_slugs),
};

fn release_a() -> Vec<Model> {
    vec![
        Model::new("library.book")
            .table("books")
            .field(Column::uuid("id").primary_key())
            .field(Column::text("title").chars(1, 200)),
    ]
}

fn release_b(slug_required: bool) -> Vec<Model> {
    let slug = Column::text("slug").chars(1, 220);
    let slug = if slug_required { slug } else { slug.nullable() };
    vec![
        Model::new("library.book")
            .table("books")
            .field(Column::uuid("id").primary_key())
            .field(Column::text("title").chars(1, 200))
            .field(slug)
            .unique("books_slug_key", &["slug"]),
    ]
}

fn release_c() -> Vec<Model> {
    vec![
        Model::new("library.book")
            .table("library_books")
            .field(Column::uuid("id").primary_key())
            .field(Column::text("title").column("name").chars(1, 200))
            .field(Column::text("slug").chars(1, 220))
            .unique("books_slug_key", &["slug"]),
    ]
}

/// Plans `models` against `set`'s history and appends the generated artifact.
fn generate(
    set: &mut Vec<Migration>,
    models: Vec<Model>,
    name: &str,
    options: PlanOptions,
) -> Artifact {
    let current = MigrationSet::ordered(set.clone()).unwrap();
    let plan = diff(
        &current.history().unwrap(),
        &desired(&models).unwrap(),
        &options,
    );
    assert!(plan.blocked.is_empty(), "{:#?}", plan.blocked);
    let mut artifacts = artifact::generate(&current, &plan, name).unwrap();
    assert_eq!(artifacts.len(), 1);
    let artifact = artifacts.remove(0);
    set.push(to_migration(&artifact, None));
    artifact
}

/// Every release's migrations, built by the planner.
fn history() -> (Vec<Migration>, Vec<Artifact>) {
    let mut set = Vec::new();
    let mut artifacts = Vec::new();
    artifacts.push(generate(
        &mut set,
        release_a(),
        "initial",
        PlanOptions::default(),
    ));
    artifacts.push(generate(
        &mut set,
        release_b(false),
        "add_slug",
        PlanOptions::default(),
    ));

    let current = MigrationSet::ordered(set.clone()).unwrap();
    let data = artifact::empty(&current, "library", "backfill_slugs", "backfill_slugs").unwrap();
    set.push(to_migration(&data, Some(BACKFILL)));
    artifacts.push(data);

    // Without the assertion that data filled it, requiring slug is blocked.
    let current = MigrationSet::ordered(set.clone()).unwrap();
    let blocked = diff(
        &current.history().unwrap(),
        &desired(&release_b(true)).unwrap(),
        &PlanOptions::default(),
    );
    assert!(blocked.blocked[0].contains("library.book.slug becomes required"));
    let filled = PlanOptions {
        filled: BTreeSet::from(["library.book.slug".to_owned()]),
        ..Default::default()
    };
    artifacts.push(generate(&mut set, release_b(true), "require_slug", filled));
    artifacts.push(generate(
        &mut set,
        release_c(),
        "rename_title",
        PlanOptions::default(),
    ));
    (set, artifacts)
}

async fn catalog(conn: &mut PgConnection) -> Vec<String> {
    let columns: Vec<(String, String, String, String)> = sqlx::query_as(
        "SELECT table_name::text, column_name::text, data_type::text, is_nullable::text
         FROM information_schema.columns WHERE table_schema = current_schema()
           AND table_name <> 'trestle_migrations'
         ORDER BY 1, 2",
    )
    .fetch_all(&mut *conn)
    .await
    .unwrap();
    let constraints: Vec<(String, String, String)> = sqlx::query_as(
        "SELECT conrelid::regclass::text, conname::text, pg_get_constraintdef(oid)
         FROM pg_constraint WHERE connamespace = current_schema()::regnamespace
           AND conrelid::regclass::text <> 'trestle_migrations'
         ORDER BY 1, 2",
    )
    .fetch_all(&mut *conn)
    .await
    .unwrap();
    columns
        .into_iter()
        .map(|(t, c, ty, n)| format!("column {t}.{c} {ty} nullable={n}"))
        .chain(
            constraints
                .into_iter()
                .map(|(t, n, d)| format!("constraint {t}.{n}: {d}")),
        )
        .collect()
}

#[test]
fn generated_sql_renames_instead_of_dropping() {
    let (_, artifacts) = history();
    let ids: Vec<&str> = artifacts.iter().map(|a| a.manifest.id.as_str()).collect();
    assert_eq!(
        ids,
        [
            "0001_initial",
            "0002_add_slug",
            "0003_backfill_slugs",
            "0004_require_slug",
            "0005_rename_title"
        ]
    );
    let rename = &artifacts[4].sql;
    assert!(
        rename.contains("ALTER TABLE books RENAME TO library_books;"),
        "{rename}"
    );
    assert!(
        rename.contains("ALTER TABLE library_books RENAME COLUMN title TO name;"),
        "{rename}"
    );
    assert!(!rename.contains("DROP"), "{rename}");
    assert!(artifacts[3].sql.contains("ALTER COLUMN slug SET NOT NULL"));
    assert_eq!(
        artifacts[4].manifest.depends_on,
        ["library.0004_require_slug"]
    );
}

#[tokio::test]
async fn fresh_replay_and_populated_upgrade_converge() {
    let (all, _) = history();
    let full = MigrationSet::ordered(all.clone()).unwrap();
    let expected = full.history().unwrap();

    // Fresh install: replay everything into an empty database.
    let fresh = TestDatabase::create().await;
    assert_eq!(migrate(fresh.options(), &full).await.unwrap().len(), 5);
    let mut fresh_conn = fresh.connect().await;
    let report = verify(&mut fresh_conn, &expected).await.unwrap();
    assert!(report.ok(), "{:#?}", report.mismatches);

    // Upgrade: release A, populated, then everything after it.
    let upgraded = TestDatabase::create().await;
    let release_a_set = MigrationSet::ordered(all[..1].to_vec()).unwrap();
    migrate(upgraded.options(), &release_a_set).await.unwrap();
    let mut conn = upgraded.connect().await;
    for title in [
        "Linear Algebra",
        "Number Theory",
        "Émile's Notes",
        "Graphs & Trees",
        "Topology",
    ] {
        sqlx::query("INSERT INTO books (id, title) VALUES (gen_random_uuid(), $1)")
            .bind(title)
            .execute(&mut conn)
            .await
            .unwrap();
    }
    assert_eq!(migrate(upgraded.options(), &full).await.unwrap().len(), 4);
    let report = verify(&mut conn, &expected).await.unwrap();
    assert!(report.ok(), "{:#?}", report.mismatches);

    let rows: Vec<(String, String)> =
        sqlx::query_as("SELECT name, slug FROM library_books ORDER BY name COLLATE \"C\"")
            .fetch_all(&mut conn)
            .await
            .unwrap();
    assert_eq!(
        rows,
        [
            ("Graphs & Trees".into(), "graphs-trees".into()),
            ("Linear Algebra".into(), "linear-algebra".into()),
            ("Number Theory".into(), "number-theory".into()),
            ("Topology".into(), "topology".into()),
            ("Émile's Notes".into(), "émile-s-notes".into()),
        ]
    );

    // Same managed schema either way, down to constraint definitions.
    assert_eq!(catalog(&mut fresh_conn).await, catalog(&mut conn).await);

    // History stays immutable, data steps included.
    let mut edited = all.clone();
    edited[2].data = Some(DataStep {
        source: "fn backfill_slugs() { /* edited after being applied */ }",
        ..BACKFILL
    });
    let err = migrate(upgraded.options(), &MigrationSet::ordered(edited).unwrap())
        .await
        .unwrap_err();
    assert!(
        matches!(err, HistoryError::DigestMismatch { ref migration, .. } if migration == "library.0003_backfill_slugs")
    );

    drop(fresh_conn);
    drop(conn);
    fresh.drop().await;
    upgraded.drop().await;
}

#[tokio::test]
async fn a_failing_data_step_rolls_back_its_migration() {
    fn fail<'a>(tx: &'a mut HistoricalTx<'_>) -> DataFuture<'a> {
        Box::pin(async move {
            tx.update(
                "library.book",
                &json!("00000000-0000-4000-8000-000000000000"),
                &[("missing", json!(1))],
            )
            .await?;
            Ok(())
        })
    }
    let (mut all, _) = history();
    all.truncate(3);
    all[2].data = Some(DataStep {
        run: DataRun::Once(fail),
        ..BACKFILL
    });
    let db = TestDatabase::create().await;
    let err = migrate(db.options(), &MigrationSet::ordered(all).unwrap())
        .await
        .unwrap_err();
    assert!(err.to_string().contains("has no field missing"), "{err}");
    let mut conn = db.connect().await;
    let status: String = sqlx::query_scalar(
        "SELECT status FROM trestle_migrations WHERE id = '0003_backfill_slugs'",
    )
    .fetch_one(&mut conn)
    .await
    .unwrap();
    assert_eq!(status, "failed");
    drop(conn);
    db.drop().await;
}

#[test]
fn replaying_the_same_models_plans_nothing() {
    let (all, _) = history();
    let set = MigrationSet::ordered(all).unwrap();
    let plan = diff(
        &set.history().unwrap(),
        &desired(&release_c()).unwrap(),
        &PlanOptions::default(),
    );
    assert!(plan.is_empty(), "{plan:#?}");
}
